CREATE TABLE `ai_analysis_requests` (`id` CHAR(36) CHARACTER SET ascii NOT NULL,`organization_id` CHAR(36) CHARACTER SET ascii NOT NULL,`workspace_id` CHAR(36) CHARACTER SET ascii NOT NULL,`opportunity_id` CHAR(36) CHARACTER SET ascii NOT NULL,`opportunity_version` INT UNSIGNED NOT NULL,`status` ENUM('queued','leased','retry_scheduled','succeeded','failed_terminal','dead_letter') NOT NULL DEFAULT 'queued',`attempt_count` INT UNSIGNED NOT NULL DEFAULT 0,`available_at` DATETIME(3) NOT NULL,`lease_owner` VARCHAR(128) CHARACTER SET ascii NULL,`lease_expires_at` DATETIME(3) NULL,`last_error_code` VARCHAR(120) CHARACTER SET ascii NULL,`input_snapshot_json` JSON NOT NULL,`input_sha256` CHAR(64) CHARACTER SET ascii NOT NULL,`prompt_contract_version` VARCHAR(80) CHARACTER SET ascii NOT NULL,`request_id` VARCHAR(128) CHARACTER SET ascii NOT NULL,`trace_id` VARCHAR(128) CHARACTER SET ascii NOT NULL,`created_by` CHAR(36) CHARACTER SET ascii NOT NULL,`created_at` DATETIME(3) NOT NULL,`updated_at` DATETIME(3) NOT NULL,PRIMARY KEY(`id`),KEY `idx_ai_request_lease`(`status`,`available_at`,`lease_expires_at`),KEY `idx_ai_request_scope`(`organization_id`,`workspace_id`,`opportunity_id`,`created_at`),CONSTRAINT `fk_ai_request_opportunity` FOREIGN KEY(`opportunity_id`) REFERENCES `opportunities`(`id`) ON DELETE CASCADE,CONSTRAINT `fk_ai_request_creator` FOREIGN KEY(`created_by`) REFERENCES `users`(`id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `ai_analysis_results` (`id` CHAR(36) CHARACTER SET ascii NOT NULL,`organization_id` CHAR(36) CHARACTER SET ascii NOT NULL,`workspace_id` CHAR(36) CHARACTER SET ascii NOT NULL,`request_id_fk` CHAR(36) CHARACTER SET ascii NOT NULL,`opportunity_id` CHAR(36) CHARACTER SET ascii NOT NULL,`result_json` JSON NOT NULL,`ai_generated` TINYINT(1) NOT NULL DEFAULT 1,`model_name` VARCHAR(200) NOT NULL,`provider_request_id` VARCHAR(200) CHARACTER SET ascii NULL,`review_status` ENUM('pending','approved','rejected') NOT NULL DEFAULT 'pending',`created_at` DATETIME(3) NOT NULL,PRIMARY KEY(`id`),UNIQUE KEY `uq_ai_result_request`(`request_id_fk`),KEY `idx_ai_result_scope`(`organization_id`,`workspace_id`,`opportunity_id`,`created_at`),CONSTRAINT `fk_ai_result_request` FOREIGN KEY(`request_id_fk`) REFERENCES `ai_analysis_requests`(`id`) ON DELETE CASCADE,CONSTRAINT `fk_ai_result_opportunity` FOREIGN KEY(`opportunity_id`) REFERENCES `opportunities`(`id`) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `ai_analysis_reviews` (`id` CHAR(36) CHARACTER SET ascii NOT NULL,`organization_id` CHAR(36) CHARACTER SET ascii NOT NULL,`workspace_id` CHAR(36) CHARACTER SET ascii NOT NULL,`result_id` CHAR(36) CHARACTER SET ascii NOT NULL,`outcome` ENUM('approved','rejected') NOT NULL,`notes` VARCHAR(1000) NOT NULL,`reviewed_by` CHAR(36) CHARACTER SET ascii NOT NULL,`request_id` VARCHAR(128) CHARACTER SET ascii NOT NULL,`trace_id` VARCHAR(128) CHARACTER SET ascii NOT NULL,`created_at` DATETIME(3) NOT NULL,PRIMARY KEY(`id`),UNIQUE KEY `uq_ai_result_review`(`result_id`),KEY `idx_ai_review_scope`(`organization_id`,`workspace_id`,`created_at`),CONSTRAINT `fk_ai_review_result` FOREIGN KEY(`result_id`) REFERENCES `ai_analysis_results`(`id`) ON DELETE CASCADE,CONSTRAINT `fk_ai_review_actor` FOREIGN KEY(`reviewed_by`) REFERENCES `users`(`id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `ai_analysis_events` (`id` CHAR(36) CHARACTER SET ascii NOT NULL,`organization_id` CHAR(36) CHARACTER SET ascii NOT NULL,`workspace_id` CHAR(36) CHARACTER SET ascii NOT NULL,`event_type` VARCHAR(120) CHARACTER SET ascii NOT NULL,`resource_id` CHAR(36) CHARACTER SET ascii NOT NULL,`actor_id` VARCHAR(128) CHARACTER SET ascii NOT NULL,`payload_json` JSON NOT NULL,`request_id` VARCHAR(128) CHARACTER SET ascii NOT NULL,`trace_id` VARCHAR(128) CHARACTER SET ascii NOT NULL,`created_at` DATETIME(3) NOT NULL,PRIMARY KEY(`id`),KEY `idx_ai_event_scope`(`organization_id`,`workspace_id`,`created_at`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `ai_analysis_outbox` (`id` CHAR(36) CHARACTER SET ascii NOT NULL,`organization_id` CHAR(36) CHARACTER SET ascii NOT NULL,`workspace_id` CHAR(36) CHARACTER SET ascii NOT NULL,`event_type` VARCHAR(120) CHARACTER SET ascii NOT NULL,`resource_id` CHAR(36) CHARACTER SET ascii NOT NULL,`payload_json` JSON NOT NULL,`status` ENUM('queued','delivered','dead_letter') NOT NULL DEFAULT 'queued',`available_at` DATETIME(3) NOT NULL,`created_at` DATETIME(3) NOT NULL,PRIMARY KEY(`id`),KEY `idx_ai_outbox_delivery`(`status`,`available_at`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `ai_analysis_operations` (`id` CHAR(36) CHARACTER SET ascii NOT NULL,`actor_id` CHAR(36) CHARACTER SET ascii NOT NULL,`route_key` VARCHAR(200) CHARACTER SET ascii NOT NULL,`idempotency_key` VARCHAR(200) CHARACTER SET ascii NOT NULL,`resource_id` CHAR(36) CHARACTER SET ascii NOT NULL,`result_json` JSON NOT NULL,`created_at` DATETIME(3) NOT NULL,PRIMARY KEY(`id`),UNIQUE KEY `uq_ai_operation`(`actor_id`,`route_key`,`idempotency_key`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
